<template>
  <div class="sbtj">
    <div class="serch">
      <el-form class="demo-ruleForm">
        <el-form-item label="监控点名称" label-width="100px">
          <el-cascader style="width: 100%" v-model="sbname" :options="options1" :props="props" clearable size="small" @change="axioss()"></el-cascader>
        </el-form-item>
        <el-form-item label="设备类型" label-width="80px">
          <el-select v-model="sbtype" placeholder="请选择设备类型" size="small" clearable filterable @change="axioss()">
            <el-option v-for="item in options2" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-search" type="primary" size="small" @click="axioss()">查询</el-button>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-plus" type="success" size="small" @click="handleAdd()">添加</el-button>
        </el-form-item>
        <el-form-item>
          <el-button icon="el-icon-delete" type="danger" size="small" @click="handleDel()">删除</el-button>
        </el-form-item>
        <el-form-item>
          <el-button size="small" @click="synchro()">ip同步</el-button>
        </el-form-item>
      </el-form>
    </div>
    <div class="table">
      <div class="jia_table">
        <el-table ref="singleTable" :row-key="getRowKey" :data="tableData" height="95%" style="width: 100%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }" @select="handleRow" @select-all="handleRows" :tree-props="{children: 'children', hasChildren: 'hasChildren'}">
          <el-table-column type="selection" width="55"></el-table-column>
          <!-- <el-table-column prop="index" label="序号" width="100" >
          <template slot-scope="scope">
            {{ scope.$index + 1 }}
          </template>
        </el-table-column> -->
          <el-table-column prop="serialNumber" label="序号" width="100"></el-table-column>
          <el-table-column prop="equipment_type" label="设备类型" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="manufacturer_type" label="厂商类型" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="equipment_name" label="设备名称" :show-overflow-tooltip="true">
            <template slot-scope="scope">
              <template v-if="scope.row.code">{{ scope.row.equipment_name }}__通道{{ scope.row.code }}</template>
              <template v-else>{{ scope.row.equipment_name }}</template>
            </template>
          </el-table-column>
          <el-table-column prop="equipment_ip" label="IP地址" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="equipment_uname" label="用户名" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="equipment_password" label="密码" :show-overflow-tooltip="true">
            <template slot-scope="scope">
              <div v-if="!scope.row.showPassword">
                <span>{{ maskPassword(scope.row.equipment_password) }}</span>
                <i class="el-icon-view" style="cursor: pointer;" @click="toggleShowPassword(scope.row)" v-if="scope.row.password"></i>
              </div>
              <div v-else>
                <span>{{ scope.row.equipment_password }}</span>
                <i class="el-icon-view" style="cursor: pointer;" @click="toggleShowPassword(scope.row)" v-if="scope.row.password"></i>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="equipment_codetype" label="码流类型" :show-overflow-tooltip="true"></el-table-column>
          <el-table-column prop="online " label="联网状态" :show-overflow-tooltip="true">
            <template slot-scope="scope">
              <span v-if="scope.row.online == 0" style="color: red;">离线</span>
              <span v-if="scope.row.online == 1" style="color: rgb(48, 245, 48);">在线</span>
            </template>
          </el-table-column>
          <!-- <el-table-column prop="flower_frames" label="花帧阈值"  :show-overflow-tooltip="true"></el-table-column> -->
          <!--        <el-table-column prop="equipment_codetype" label="输入框" align='center' :show-overflow-tooltip="true">-->
          <!--          <template slot-scope="scope">-->
          <!--            <el-input v-model="scope.row.equipment_codetype" placeholder="请输入内容"></el-input>-->
          <!--          </template>-->
          <!--        </el-table-column>-->
          <el-table-column label="操作" align="center" width="200">
            <template slot-scope="scope">
              <el-button type="text" v-if="scope.row.equipment_type == '摄像头' || scope.row.equipment_type == 'AI单光摄像头' || (scope.row.equipment_type == 'AI双光摄像头' && scope.row.children)" @click="handleClickUpdate(scope.row.id,scope.row)">修改</el-button>
              <el-button type="text" v-if="scope.row.equipment_type == 'AI单光摄像头' || (scope.row.equipment_type == 'AI双光摄像头' && scope.row.children)" @click="synchros(scope.row)">数据同步</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="tableData.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>
      <div class="page">
        <el-pagination @current-change="handleCurrentChange" @size-change="handleSizeChange" :current-page.sync="currentPage" :page-size="pagesize" :page-sizes="pagesizes" background layout="total, prev, pager, next, jumper,sizes" :total="pagelength">
        </el-pagination>
      </div>
    </div>
    <el-dialog :title="title" :visible.sync="dialogVisible" width="50%" @close="handleClose">
      <el-form :model="ruleForm" :rules="rules" ref="ruleForms" class="sbtj_diaForm" label-position="top">
        <el-form-item v-if="statusType" label="设备类型" :label-width="formLabelWidth" prop="equipment_type">
          <el-select v-model="ruleForm.equipment_type" placeholder="请选择设备类型" size="small" clearable filterable style="width: 90%" @change="handlelxj(ruleForm.equipment_type)">
            <el-option v-for="item in options3" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item v-else label="设备类型" :label-width="formLabelWidth" prop="equipment_type">
          <el-select v-model="ruleForm.equipment_type" placeholder="请选择设备类型" size="small" clearable filterable style="width: 90%" @change="handlelxj(ruleForm.equipment_type)">
            <el-option v-for="item in options7" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="设备名称" :label-width="formLabelWidth" prop="equipment_name">
          <el-input style="width: 90%" v-model="ruleForm.equipment_name" placeholder="请输入设备名称"></el-input>
        </el-form-item>
        <!-- <div class="lxj" v-if="(ruleForm.equipment_type == 2 || ruleForm.equipment_type == 3) && this.title == '新增设备'"> -->
        <div class="lxj" v-if="ruleForm.equipment_type == 2 && this.title == '新增设备'">
          <div v-for="(item, index) in sbTable" :key="index" class="lxj_box">
            <div class="lxj_box_content">
              <span class="lxj_box_content_title">设备名称</span>
              <el-input v-model="item.equipment_name" placeholder="请输入内容" class="lxj_box_content_input"></el-input>
            </div>
            <div class="lxj_box_content">
              <span class="lxj_box_content_title">设备IP</span>
              <el-input v-model="item.equipment_ip" placeholder="请输入内容" class="lxj_box_content_input"></el-input>
            </div>
            <div class="lxj_box_content">
              <span class="lxj_box_content_title">设备通道</span>
              <el-input v-model="item.equipment_aisles" placeholder="请输入内容" class="lxj_box_content_input"></el-input>
            </div>
            <div class="lxj_box_button">
              <el-button type="primary" icon="el-icon-plus" @click="handlesbadd()"></el-button>
              <el-button type="danger" icon="el-icon-minus" @click="handlesbdel(index)"></el-button>
            </div>
          </div>
        </div>
        <el-form-item label="厂商类型" :label-width="formLabelWidth" prop="manufacturer_type">
          <el-select v-model="ruleForm.manufacturer_type" placeholder="请选择厂商类型" size="small" clearable filterable @change="showfn(ruleForm.manufacturer_type)" style="width: 90%">
            <el-option v-for="item in options4" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="读卡器ip" :label-width="formLabelWidth" prop="equipment_ip" v-if="showType">
          <!-- <el-select v-model="ruleForm.uwb_ip" placeholder="请选择UWB-id" size="small" clearable filterable style="width: 90%">
            <el-option v-for="item in options40" :key="item.id" :label="item.uwb_ip" :value="item.uwb_ip"> </el-option>
          </el-select> -->
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.uwb_ip" placeholder="请输入读卡器ip"></el-input>
        </el-form-item>
        <el-form-item label="单位名称" :label-width="formLabelWidth" prop="Mine_id">
          <el-select v-model="ruleForm.Mine_id" placeholder="请选择单位名称" size="small" clearable filterable style="width: 90%">
            <el-option v-for="item in options5" :key="item.id" :label="item.mine_name" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="用户名" :label-width="formLabelWidth" prop="equipment_uname">
          <el-input style="width: 90%" v-model="ruleForm.equipment_uname" placeholder="请输入用户名"></el-input>
        </el-form-item>
        <el-form-item label="密码" :label-width="formLabelWidth" prop="equipment_password">
          <el-input style="width: 90%" v-model="ruleForm.equipment_password" placeholder="请输入密码" show-password></el-input>
        </el-form-item>
        <el-form-item label="码流类型" :label-width="formLabelWidth" prop="equipment_codetype">
          <el-select v-model="ruleForm.equipment_codetype" placeholder="请选择码流类型" size="small" clearable filterable style="width: 90%">
            <el-option v-for="item in options6" :key="item.id" :label="item.value" :value="item.id"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="IP地址" :label-width="formLabelWidth" prop="equipment_ip">
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.equipment_ip" placeholder="请输入IP地址"></el-input>
        </el-form-item>
        <!-- <el-form-item label="海康安防平台URL流" :label-width="formLabelWidth" prop="hik_url">
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.hik_url" placeholder="海康安防平台URL流"></el-input>
        </el-form-item> -->
        <!-- <el-form-item label="海康安防平台URL流" :label-width="formLabelWidth" prop="flower_frames">
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.flower_frames" placeholder="海康安防平台URL流"></el-input>
        </el-form-item> -->
        <!-- <el-form-item label="通道" :label-width="formLabelWidth" prop="equipment_aisles">
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.equipment_aisles" placeholder="请输入通道"></el-input>
        </el-form-item> -->
        <!-- <el-form-item label="花帧阈值" :label-width="formLabelWidth" prop="flower_frames">
          <el-input autocomplete="off" style="width: 90%" v-model="ruleForm.flower_frames" placeholder="请输入花帧阈值"></el-input><br />
          <span style="font-size: 12px; color: red; line-height: 20px">非必填:该监控点返回图片清晰度调整</span>
        </el-form-item> -->
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="dialogVisible = false">取 消</el-button>
        <el-button type="primary" @click="handleSure()">确 定</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  name: "sbtj",
  data() {
    return {
      options40:[],
      showType: false,
      statusType:true,
      sbname: "",
      sbtype: "",
      options1: [],
      options2: [],
      options3: [],
      options4: [],
      options5: [],
      options6: [],
      options7: [],
      props: {
        checkStrictly: false,
        emitPath: false,
        value: "id",
        label: "equipment_name",
      },
      tableData: [],
      currentPage: 1, //默认开始页面 this.$store.state.pages  $store.state.loginuser
      pagenumber: 1, //第几页
      pagesize: 15, //每页的数据条数
      pagelength: 0, //默认数据总数
      pagesizes: [15, 35, 50, 100, 150, 200, 300],
      multipleSelection: [],

      dialogVisible: false,
      formLabelWidth: "80px",
      ruleForm: {
        equipment_type: "",
        equipment_name: "",
        manufacturer_type: "",
        equipment_ip: "",
        equipment_uname: "",
        equipment_password: "",
        equipment_aisles: "",
        equipment_codetype: "",
        Mine_id: "",
        uwb_ip:'',
        // hik_url:"",
      },
      rules: {
        equipment_ip: [
          {
            pattern: /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
            message: '请输入有效的IP地址',
            trigger: ['blur', 'change']
          }
        ]
      },
      sbTable: [],
      title: "",
    };
  },
  methods: {
    showfn(e){
      if(e == '8' || e == "艾斯卡普"){
        this.showType = true;
      }else{
        this.showType = false;
      }
    },
    // 处理第一级节点
    addSerialNumber(data, parentIndex = 0) {
      let index = parentIndex; // 初始序号从父级的序号开始
      data.forEach((item, idx) => {
        item.serialNumber = ++index; // 增加序号
        if (item.children && item.children.length) {
          // 如果有子节点，递归处理子节点
          this.addSerialNumber2(item.children, 0, item.serialNumber);
        }
      });
    },
    // 处理第二级节点
    addSerialNumber2(data, parentIndex = 0, parent) {
      let index = parentIndex; // 初始序号从父级的序号开始
      data.forEach((item, idx) => {
        item.serialNumber = String(parent) + "-" + (++index); // 增加序号
        if (item.children && item.children.length) {
          // 如果有子节点，递归处理子节点
          this.addSerialNumber2(item.children, 0, item.serialNumber);
        }
      });
    },
    maskPassword(password) {
      if (password) {
        return '*'.repeat(password.length); // Replace with your own masking logic
      } else {
        return password
      }
    },
    toggleShowPassword(row) {
      // 确保 row.showPassword 是响应式的
      if (!row.hasOwnProperty('showPassword')) {
        this.$set(row, 'showPassword', false); // 初始化 showPassword
      }
      row.showPassword = !row.showPassword;
    },
    getRowKey(row) {
      return row.id;
    },
    handleCurrentChange(val) {
      this.pagenumber = val;
      this.axioss();
    },
    handleSizeChange(val) {
      this.pagesize = val;
      this.axioss();
    },
    handleRow(val) {
      // console.log(val)
      this.multipleSelection = val;
    },
    handleRows(val) {
      // console.log(val)
      this.multipleSelection = val;
    },
    handleSelect1(a) {
      this.$http
        .get(this.$url.url_5000 + "/model_view/type_select", {})
        .then((response) => {
          console.log(response);
          if (response.data.code === 200) {
            if (a === 2) {
              // this.options3 = [response.data.equipment_type[0]];
              this.options3 = [
  {
    "id": "1",
    "value": "摄像头"
  },
  {
    "id": "6",
    "value": "AI单光摄像头"
  },
  {
    "id": "7",
    "value": "AI双光摄像头"
  }
];
              this.options4 = response.data.manufacturer_type;
              this.options5 = response.data.mine_list;
              this.options6 = response.data.equipment_codetype;
            } else {
              this.options1 = response.data.equipment_list;
              this.options2 = response.data.equipment_type;
            }
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    axioss() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/equipment_show", {
          params: {
            equipment_name: this.sbname,
            equipment_type: this.sbtype,
            page: this.pagenumber,
            per_page: this.pagesize,
          },
        })
        .then((response) => {
          console.log(response);
          if (response.data.code === 200) {
            this.tableData = response.data.data_list.data.map(v => {
              return { ...v, showPassword: false }
            })
            this.pagelength = response.data.data_list.data.length;
            this.addSerialNumber(this.tableData);
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    handleAdd() {
      this.title = "新增设备";
      this.dialogVisible = true;
      this.statusType = true;
        this.showType = false;
      this.ruleForm.equipment_type = this.options3[0].id;
      this.ruleForm.equipment_name = '';
      this.ruleForm.manufacturer_type = this.options4[0].id;
      this.ruleForm.Mine_id = this.options5[0].id;
      this.ruleForm.equipment_uname = '';
      this.ruleForm.uwb_ip = '';
      this.ruleForm.equipment_password = '';
      this.ruleForm.equipment_codetype = this.options6[0].id;
      // this.ruleForm = {
      //   equipment_type: "",
      //   equipment_name: "",
      //   manufacturer_type: "",
      //   equipment_ip: "",
      //   equipment_uname: "",
      //   equipment_password: "",
      //   equipment_aisles: "",
      //   equipment_codetype: "",
      //   Mine_id: "",
      // };
      // this.handleSelect1(2)
    },
    // 按钮ip同步
    synchro(){
      this.$http
        .post(this.$url.url_5000 + "/model_view/sync_aicam_ip", {
          
        })
        .then((response) => {
          if (response.data.code === 200) {
            this.$message({
              message: response.data.msg,
              type: "success",
            });
            this.axioss();
            this.handleClose();
          } else {
            this.$message({
              message: response.data.msg,
              type: "warning",
            });
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 表格数据同步
    synchros(row){
      this.$http
        .post(this.$url.url_5000 + "/ai_camera_view/algorithm_sync_aicam", {
          equipment_id:row.id
        })
        .then((response) => {
          if (response.data.code === 200) {
            this.$message({
              message: response.data.msg,
              type: "success",
            });
            this.axioss();
            this.handleClose();
          } else {
            this.$message({
              message: response.data.msg,
              type: "warning",
            });
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    handleDel() {
      console.log(this.multipleSelection);
      this.$http
        .post(this.$url.url_5000 + "/model_view/equipment_delete", {
          equipment_id: this.multipleSelection,
        })
        .then((response) => {
          console.log(response);
          if (response.data.code === 200) {
            this.$message({
              message: response.data.msg,
              type: "success",
            });
            this.axioss();
            this.handleClose();
          } else {
            this.$message({
              message: response.data.msg,
              type: "warning",
            });
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    handlelxj(a) {
      // this.ruleForm = {
      //   equipment_type: "",
      //   equipment_name: "",
      //   manufacturer_type: "",
      //   equipment_ip: "",
      //   equipment_uname: "",
      //   equipment_password: "",
      //   equipment_aisles: "",
      //   equipment_codetype: "",
      //   Mine_id: "",
      // };
      if (a == 2 || a == 3) {
        this.sbTable = [
          {
            equipment_name: "",
            equipment_ip: "",
            equipment_aisles: "",
          },
        ];
      } else {
        this.sbTable = [];
      }
      // if (a == 3) {
      //   this.ruleForm.manufacturer_type = this.options4[0].id;
      //   this.ruleForm.Mine_id = this.options5[0].id;
      //   this.ruleForm.equipment_uname = 'admin';
      //   this.ruleForm.equipment_password = '';
      //   this.ruleForm.equipment_codetype = this.options6[0].id;
      // }
    },
    handlesbadd() {
      let a = {
        equipment_name: "",
        equipment_ip: "",
        equipment_aisles: "",
      };
      this.sbTable.push(a);
    },
    handleSure() {
      let forms = {
        equipment_type: this.ruleForm.equipment_type,
        equipment_name: this.ruleForm.equipment_name,
        manufacturer_type: this.ruleForm.manufacturer_type,
        equipment_ip: this.ruleForm.equipment_ip,
        equipment_uname: this.ruleForm.equipment_uname,
        equipment_password: this.ruleForm.equipment_password,
        equipment_aisles: this.ruleForm.equipment_aisles,
        equipment_codetype: this.ruleForm.equipment_codetype,
        Mine_id: this.ruleForm.Mine_id,
        uwb_ip: this.ruleForm.uwb_ip,
        // children_list: this.sbTable,
        children_list: this.ruleForm.equipment_type == 3 ? [{ equipment_name: "", equipment_ip: "", equipment_aisles: "" }, { equipment_name: "", equipment_ip: "", equipment_aisles: "" }] : this.sbTable,
        flower_frames: this.ruleForm.flower_frames,
        // hik_url:this.ruleForm.hik_url
      };
      let forms2 = {
        id: this.ruleForm.id,
        equipment_type: this.ruleForm.equipment_type,
        equipment_name: this.ruleForm.equipment_name,
        manufacturer_type: this.ruleForm.manufacturer_type,
        equipment_ip: this.ruleForm.equipment_ip,
        equipment_uname: this.ruleForm.equipment_uname,
        equipment_password: this.ruleForm.equipment_password,
        equipment_aisles: this.ruleForm.equipment_aisles,
        equipment_codetype: this.ruleForm.equipment_codetype,
        Mine_id: this.ruleForm.Mine_id,
        uwb_ip: this.ruleForm.uwb_ip,
        children_list: this.sbTable,
        flower_frames: this.ruleForm.flower_frames,
        // hik_url:this.ruleForm.hik_url
      };
      if (this.title == "新增设备") {
        this.$http
          .post(this.$url.url_5000 + "/model_view/equipment_create", forms)
          .then((response) => {
            console.log(response);
            if (response.data.code === 200) {
              this.$message({
                message: response.data.msg,
                type: "success",
              });
              this.axioss();
              this.handleClose();
            } else {
              this.$message({
                message: response.data.msg,
                type: "warning",
              });
            }
          })
          .catch(function (response) {
            console.log(response);
          });
      } else if (this.title == "修改设备") {
        console.log(this.ruleForm);
        this.$http
          .post(
            this.$url.url_5000 + "/model_view/equipment_update",
            {
              ...forms2,
              // equipment_name: this.ruleForm.id,
              type: 2,
            },
            {
              headers: {
                "Content-Type": "multipart/form-data",
              },
            }
          )
          .then((response) => {
            if (response.data.code === 200) {
              this.$message({
                message: response.data.msg,
                type: "success",
              });
              this.axioss();
              this.handleClose();
            } else {
              this.$message({
                message: response.data.msg,
                type: "warning",
              });
            }
          })
          .catch((rek) => {
            console.log(rek);
          });
      }
    },
    handlesbdel(a) {
      // console.log(a)
      if (this.sbTable.length > 1) {
        this.sbTable.splice(a, 1);
      }
      // console.log(this.sbTable)
    },
    handleClose() {
      this.$refs.ruleForms.resetFields();
      this.sbTable = [];
      this.$nextTick(() => {
        this.dialogVisible = false;
      });
    },
    // 修改按钮
    handleClickUpdate(id,rows) {
      this.$http
        .post(
          this.$url.url_5000 + "/model_view/equipment_update",
          {
            equipment_name: id,
            type: 1,
          },
          {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          }
        )
        .then((response) => {
          this.title = "修改设备";
          // this.options4.map(v=>{
          //   if(v.value == response.data.data.manufacturer_type){
          //     return v.id
          //   }
          //   console.log('*****')
          //   console.log(v)
          //   console.log('*****')
          //   // if(v.value == response.data.data.manufacturer_type){
          //     // return v.id
          //   // }
          // })
          this.ruleForm = response.data.data;
          this.showfn(this.ruleForm.manufacturer_type)
          this.options7 = [];
          if (this.ruleForm.equipment_codetype) {
            this.ruleForm.equipment_codetype = this.options6.find((v) => v.value == this.ruleForm.equipment_codetype).id;
          }
          if (this.ruleForm.equipment_type) {
            // this.ruleForm.equipment_type = this.options3.find((v) => v.value == this.ruleForm.equipment_type).id;
            // if(this.options2.find((v) => v.value == this.ruleForm.equipment_type).id){
            //   this.ruleForm.equipment_type = this.options2
            // }
            this.statusType = false;
            console.log(rows)
            this.ruleForm.equipment_type = this.options2.find((v) => v.value == this.ruleForm.equipment_type).id;
            // this.ruleForm.equipment_type = rows.equipment_type_num
            this.options7 = [
              {
                value: rows.equipment_type,
                id: this.ruleForm.equipment_type
              }
            ]
          }
          if (this.ruleForm.manufacturer_type) {
            this.ruleForm.manufacturer_type = this.options4.find((v) => v.value == this.ruleForm.manufacturer_type).id;
          }
          this.dialogVisible = true;
        })
        .catch((rek) => {
          console.log(rek);
        });
    },
  },
  mounted() {
    this.handleSelect1();
    this.handleSelect1(2);
    this.axioss();
  },
};
</script>

